package com.asisten.bantu;
import android.Manifest; import android.content.Context; import android.content.pm.PackageManager; import android.os.*; import android.speech.tts.TextToSpeech; import android.widget.Button; import android.widget.TextView; import android.widget.Toast;
import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity; import androidx.camera.core.*; import androidx.camera.lifecycle.ProcessCameraProvider; import androidx.camera.view.PreviewView; import androidx.core.app.ActivityCompat; import androidx.core.content.ContextCompat;
import com.google.common.util.concurrent.ListenableFuture; import com.google.mlkit.vision.common.InputImage; import com.google.mlkit.vision.objects.ObjectDetection; import com.google.mlkit.vision.objects.defaults.ObjectDetectorOptions;
import java.util.Locale; import java.util.concurrent.Executor;
public class NavigationActivity extends AppCompatActivity implements TextToSpeech.OnInitListener {
private PreviewView previewView; private TextView tvStatus, tvObstacle; private TextToSpeech tts; private ImageAnalysis imageAnalysis; private ProcessCameraProvider cameraProvider; private Executor mainExecutor; private boolean isNavigating = false; private Handler handler = new Handler(Looper.getMainLooper()); private Vibrator vibrator;
@Override protected void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_navigation);previewView=findViewById(R.id.previewViewNav);tvStatus=findViewById(R.id.tvNavStatus);tvObstacle=findViewById(R.id.tvObstacle);Button a=findViewById(R.id.btnStartNav);Button b=findViewById(R.id.btnStopNav);tts=new TextToSpeech(this,this);mainExecutor=ContextCompat.getMainExecutor(this);vibrator=(Vibrator)getSystemService(Context.VIBRATOR_SERVICE);a.setOnClickListener(v->startNavigation());b.setOnClickListener(v->stopNavigation());if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.CAMERA},102);else startCamera();}
private void startCamera(){ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{cameraProvider=f.get();Preview p=new Preview.Builder().build();p.setSurfaceProvider(previewView.getSurfaceProvider());imageAnalysis=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();imageAnalysis.setAnalyzer(mainExecutor,ip->{if(!isNavigating){ip.close();return;}try{InputImage img=InputImage.fromMediaImage(ip.getImage(),ip.getImageInfo().getRotationDegrees());detectObstacle(img);}catch(Exception e){}finally{ip.close();}});cameraProvider.unbindAll();cameraProvider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,p,imageAnalysis);}catch(Exception e){Toast.makeText(this,"Gagal kamera",Toast.LENGTH_SHORT).show();}},mainExecutor);}
private void startNavigation(){isNavigating=true;tvStatus.setText("🦯 TONGKAT AKTIF");speak("Mode tongkat aktif. Getar jika ada halangan.");}
private void stopNavigation(){isNavigating=false;tvStatus.setText("Berhenti");speak("Tongkat berhenti");}
private void detectObstacle(InputImage im){ObjectDetectorOptions o=new ObjectDetectorOptions.Builder().setDetectorMode(ObjectDetectorOptions.STREAM_MODE).enableMultipleObjects().enableClassification().build();ObjectDetection.getClient(o).process(im).addOnSuccessListener(objs->{if(!isNavigating)return;if(objs.isEmpty()){runOnUiThread(()->{tvObstacle.setText("✅ Aman");tvObstacle.setBackgroundColor(0xFF00C853);});return;}float la=0;String lb="";for(com.google.mlkit.vision.objects.DetectedObject obj:objs){float ar=obj.getBoundingBox().width()*obj.getBoundingBox().height();if(ar>la){la=ar;if(!obj.getLabels().isEmpty())lb=obj.getLabels().get(0).getText();else lb="halangan";}}String w;int vib;if(la>150000){w="⛔ BAHAYA DEKAT! "+lb+"! Berhenti!";vib=3;}else if(la>70000){w="⚠️ Ada "+lb+" 2 meter";vib=2;}else if(la>20000){w="Ada "+lb+" jauh";vib=1;}else{w="✅ Aman "+lb;vib=0;}runOnUiThread(()->{tvObstacle.setText(w);if(vib>=2)tvObstacle.setBackgroundColor(0xFFD32F2F);else if(vib==1)tvObstacle.setBackgroundColor(0xFFFF9800);else tvObstacle.setBackgroundColor(0xFF00C853);});if(vib>0){vibrate(vib);if(la>70000)speak(w);}}).addOnFailureListener(e->{});}
private long lv=0;private void vibrate(int l){long n=System.currentTimeMillis();if(n-lv<1500)return;lv=n;try{if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O){if(l==3)vibrator.vibrate(VibrationEffect.createWaveform(new long[]{0,200,100,200,100,400},-1));else if(l==2)vibrator.vibrate(VibrationEffect.createWaveform(new long[]{0,300,100,300},-1));else vibrator.vibrate(VibrationEffect.createOneShot(200,VibrationEffect.DEFAULT_AMPLITUDE));}else vibrator.vibrate(500);}catch(Exception e){}}
private void speak(String s){if(tts!=null)tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,null);}
@Override public void onInit(int st){if(st==TextToSpeech.SUCCESS){tts.setLanguage(new Locale("id","ID"));tts.setSpeechRate(0.9f);}}
@Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}
}
